class Solution {
  public long maxAlternatingSum(int[] nums) {
    long NEG = Long.MIN_VALUE / 4;
    long[][] dp = {{NEG, NEG}, {NEG, NEG}};
    long best = Long.MIN_VALUE;
    for (int x : nums) {
      long[][] nd = {{NEG, NEG}, {NEG, NEG}};
      nd[1][0] = Math.max(nd[1][0], x);
      for (int par = 0; par < 2; par++) {
        for (int del = 0; del < 2; del++) {
          long cur = dp[par][del];
          if (cur == NEG) continue;
          long ext = cur + (par == 0 ? x : -x);
          nd[1 - par][del] = Math.max(nd[1 - par][del], ext);
          if (del == 0) nd[par][1] = Math.max(nd[par][1], cur);
        }
      }
      dp = nd;
      for (int par = 0; par < 2; par++)
        for (int del = 0; del < 2; del++) best = Math.max(best, dp[par][del]);
    }
    return best;
  }
}
